      if (saved === 'id' || saved === 'en') {
        setLanguageState(saved);
      }
    } catch {
      // ignore
    }
    setIsHydrated(true);
  }, []);

  const setLanguage = (lang: Language) => {
    setLanguageState(lang);
    try {
      localStorage.setItem('sevaya_lang', lang);
    } catch {
      // ignore
    }
  };

  // Selama initial hydration, selalu gunakan 'id' agar server dan browser 100% cocok
  const currentLang = isHydrated ? language : 'id';

