      allElements.forEach((el) => {
        if (
          el.textContent &&
          (el.textContent.includes('Cek Ongkir Biteship') ||
            el.textContent.includes('Simulasi Ongkir') ||
            el.textContent.includes('Kalkulator Ongkir'))
        ) {
          const container = el.closest('div.rounded-2xl, div.rounded-xl, section, div[class*="border"]');
          if (container && container instanceof HTMLElement) {
            container.style.display = 'none';
          }
        }
      });
    };

    hideBiteship();
    const interval = setInterval(hideBiteship, 500);
    return () => clearInterval(interval);
  }, [pathname]);

